-- DROP TYPE drops a domain as DROP DOMAIN does, with the same dependency
-- report, and frees the domain's slot, so creating and dropping more domains
-- than the catalog holds at once never runs out.
CREATE DOMAIN dt865 AS text CHECK (length(VALUE) < 5);
CREATE DOMAIN dq865 AS text;
CREATE DOMAIN dn865 AS integer CHECK (VALUE > 0);
CREATE DOMAIN dp865 AS dt865;
CREATE TABLE t865 (a dt865, b dq865);
CREATE TYPE r865 AS (x dn865);
DROP TYPE dq865;
DROP TYPE dt865;
DROP TYPE dt865 CASCADE;
DROP TYPE IF EXISTS dt865;
DROP TYPE dn865;
DROP TYPE dn865 CASCADE;
SELECT typname, typtype FROM pg_type WHERE typnamespace = 'public'::regnamespace
  AND typtype = 'd' ORDER BY 1;
SELECT attname FROM pg_attribute WHERE attrelid = 't865'::regclass AND attnum > 0
  AND NOT attisdropped ORDER BY attnum;
SELECT attname FROM pg_attribute WHERE attrelid = 'r865'::regclass AND attnum > 0
  AND NOT attisdropped ORDER BY attnum;
